<?php require __DIR__.'/../../includes/admin_auth.php';$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$id=(int)$_POST['id'];$next=['confirm'=>'CONFIRMED','reject'=>'REJECTED','check_in'=>'CHECKED_IN','check_out'=>'CHECKED_OUT','cancel'=>'CANCELLED'][$_POST['action']??'']??null;if($next){$s=$pdo->prepare('SELECT user_id,reservation_number FROM reservations WHERE id=?');$s->execute([$id]);$r=$s->fetch();if($r){$pdo->prepare('UPDATE reservations SET status=? WHERE id=?')->execute([$next,$id]);notify($r['user_id'],'Reservation update','Your reservation '.$r['reservation_number'].' is now '.$next.'.','RESERVATION');log_action(user()['id'],'RESERVATION_'.$next,'reservation',$id,'Updated '.$r['reservation_number']);flash('success','Reservation updated.');}}header('Location:index.php');exit;}$rows=$pdo->query("SELECT r.*,rm.title,rm.room_number,u.first_name,u.last_name FROM reservations r JOIN rooms rm ON rm.id=r.room_id JOIN users u ON u.id=r.user_id ORDER BY r.created_at DESC")->fetchAll();$pageTitle='Manage reservations';require __DIR__.'/../../includes/header.php';?><h1>Reservations</h1><div class="panel"><table><tr><th>Reservation</th><th>Guest</th><th>Room</th><th>Stay</th><th>Status</th><th>Action</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['reservation_number'])?></td><td><?=e($r['first_name'].' '.$r['last_name'])?></td><td><?=e($r['title'].' #'.$r['room_number'])?></td><td><?=e($r['check_in'].' → '.$r['check_out'])?></td><td><?=e($r['status'])?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$r['id']?>"><select name="action"><option value="confirm">Confirm</option><option value="check_in">Check in</option><option value="check_out">Check out</option><option value="reject">Reject</option><option value="cancel">Cancel</option></select><button class="small">Update</button></form></td></tr><?php endforeach;?></table></div><?php require __DIR__.'/../../includes/footer.php'; ?>
